<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import type { Api } from './api'
const props=defineProps<{api:Api;shortcuts?:{key:string;name:string;icon:string}[]}>()
const emit=defineEmits<{navigate:[key:string]}>()
const loading=ref(false),error=ref('')
const data=ref<Record<string,Record<string,number|string>>|null>(null)
const groups:Record<string,string>={people:'已入档人才',parse_tasks:'解析及机制任务',match_entries:'本人发起的匹配明细',assessments:'测评任务',chat_jobs:'本人聊天与语义任务'}
const sum=(key:string)=>Object.values(data.value?.[key]||{}).reduce<number>((total,value)=>total+Number(value||0),0)
const cards=computed(()=>[{label:'人才档案',value:sum('people'),note:`内部 ${data.value?.people?.internal||0} / 外部 ${data.value?.people?.external||0}`},{label:'处理中任务',value:Number(data.value?.parse_tasks?.queued||0)+Number(data.value?.parse_tasks?.running||0),note:'当前授权范围 · 逐文件处理'},{label:'待参与测评',value:Number(data.value?.assessments?.pending||0)+Number(data.value?.assessments?.answering||0),note:'按测评读权与当前绑定统计'},{label:'已评估匹配明细',value:Number(data.value?.match_entries?.evaluated||0),note:'本人发起 · 包含历史执行'}])
const flowNames:Record<string,string>={talents:'查看人才档案',candidates:'上传与筛选简历',requirements:'创建岗位 JD',assessments:'管理与参与测评',accounts:'管理账号授权'}
const flowNotes:Record<string,string>={talents:'事实、来源与测评',candidates:'逐文件进度 · 筛选与核对',requirements:'JD辅助 · 有效版本与匹配',assessments:'固定试卷 · 规则评分',accounts:'账号 · 角色 · 绑定'}
const labels:Record<string,string>={internal:'内部员工',external:'外部候选人',queued:'待处理',running:'处理中',pending:'待参与 / 待处理',answering:'作答中',submitted:'已提交待评分',completed:'已完成',succeeded:'成功',failed:'失败',evaluated:'已评估'}
async function load(){loading.value=true;error.value='';try{data.value=await props.api('/workbench')}catch(e){error.value=(e as Error).message;ElMessage.error(error.value)}finally{loading.value=false}}
onMounted(load)
</script>
<template>
  <div class="title-row"><div><p class="eyebrow">OVERVIEW / 人才业务概览</p><h1>工作台</h1><p class="muted">统一人才档案、岗位需求与测评信息，从真实数据出发。</p></div><el-button :loading="loading" @click="load">刷新统计</el-button></div>
  <section class="workspace-intro"><div><p class="eyebrow">CONNECTED TALENT, CLEARER DECISIONS</p><h2>把人才信息，连接成业务线索</h2><p>从一份简历开始，到一份有证据的岗位匹配结果。<br>当前视角：仅展示此账号已获授权的数据。</p></div><svg viewBox="0 0 180 100" fill="none" aria-hidden="true"><path d="M35 50h50l30-30h35M85 50l30 30h35" stroke="#79b8aa" stroke-width="2"/><rect x="10" y="32" width="38" height="38" rx="10" fill="#087f79"/><path d="m21 50 7 7 12-14" stroke="white" stroke-width="2"/><circle cx="85" cy="50" r="9" fill="white" stroke="#79b8aa" stroke-width="2"/><rect x="136" y="4" width="36" height="36" rx="9" fill="#add6c8"/><rect x="136" y="64" width="36" height="30" rx="9" fill="#add6c8"/></svg></section>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <div v-loading="loading" class="overview-stats"><article v-for="card in cards" :key="card.label"><span>{{card.label}}</span><strong>{{data?card.value:'—'}}</strong><small>{{card.note}}</small></article></div>
  <div class="overview-body"><el-card><template #header><strong>从这里开始</strong></template><div v-if="shortcuts?.length" class="overview-flow"><a v-for="(item,index) in shortcuts" :key="item.key" :href="'#'+item.key" @click.prevent="emit('navigate',item.key)"><span>0{{index+1}} ↗</span><b>{{flowNames[item.key]||item.name}}</b><small>{{flowNotes[item.key]}}</small></a></div><el-empty v-else description="当前账号没有可用业务快捷入口，请通过左侧授权菜单操作" :image-size="48"/></el-card>
  <el-card><template #header><strong>待办与处理进展</strong></template><div class="overview-todo"><div><h3>简历与文件任务</h3><p>排队 {{data?.parse_tasks?.queued||0}} · 处理中 {{data?.parse_tasks?.running||0}} · 失败 {{data?.parse_tasks?.failed||0}}</p></div><span class="status-dot" aria-hidden="true"></span></div><div class="overview-todo"><div><h3>测评参与进展</h3><p>待参与 {{data?.assessments?.pending||0}} · 作答中 {{data?.assessments?.answering||0}} · 已完成 {{data?.assessments?.completed||0}}</p></div></div><p class="muted">统计为当前授权范围；任务历史保留，不等同于新增人数。</p></el-card></div>
  <el-card v-if="data" class="activity-summary"><template #header><strong>业务统计明细</strong><span class="muted">　实时授权口径</span></template><div class="summary-groups"><section v-for="(name,key) in groups" :key="key"><h3>{{name}}</h3><p v-for="(value,state) in data[key]" :key="state">{{labels[state]||state}}<strong>{{value}}</strong></p><p v-if="!Object.keys(data[key]||{}).length" class="muted">当前范围暂无记录</p><small>{{data.definitions[key]}}</small></section></div></el-card>
</template>
<style scoped>
.workspace-intro{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:26px 30px;border:1px solid #d7e7df;border-radius:12px;background:linear-gradient(110deg,#e4f2ec,#edf5f2);margin:0 0 24px}.workspace-intro h2{font-size:21px;margin:0 0 10px}.workspace-intro p:not(.eyebrow){font-size:13px;color:#567970;margin:0;line-height:1.8}.workspace-intro svg{width:160px;height:90px;flex-shrink:0}.overview-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px}.overview-stats article{border:1px solid var(--border);background:var(--surface);border-radius:10px;padding:20px 22px}.overview-stats span{color:var(--text-secondary);font-size:12px}.overview-stats strong{display:block;font-size:31px;font-weight:600;margin:10px 0;font-variant-numeric:tabular-nums}.overview-stats small{font-size:11px;color:var(--accent)}.overview-body{display:grid;grid-template-columns:1.55fr 1fr;gap:20px;margin-bottom:20px}.overview-body>.el-card{margin:0}.overview-flow{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.overview-flow a{display:block;border:1px solid var(--border);border-radius:8px;padding:17px;text-decoration:none;color:var(--text)}.overview-flow a:hover{border-color:var(--accent);background:var(--accent-soft)}.overview-flow span{font-size:11px;color:var(--accent);font-weight:700}.overview-flow b{display:block;font-size:13px;margin:10px 0}.overview-flow small{font-size:11px;color:var(--text-secondary);line-height:1.7}.overview-todo{display:flex;justify-content:space-between;align-items:center;padding:15px 0;border-bottom:1px solid var(--border)}.overview-todo h3{font-size:13px;margin:0 0 6px}.overview-todo p{font-size:12px;color:var(--text-secondary);margin:0}.status-dot{width:7px;height:7px;border-radius:50%;background:var(--accent)}.summary-groups{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.summary-groups h3{font-size:13px;margin:0 0 14px}.summary-groups p{display:flex;justify-content:space-between;font-size:12px;margin:8px 0;color:var(--text-secondary)}.summary-groups small{display:block;font-size:11px;line-height:1.8;color:var(--text-secondary);border-top:1px solid var(--border);padding-top:10px}.activity-summary{margin-top:0!important}.el-card :deep(.el-card__header){border-bottom:0;padding-bottom:0;font-size:15px}@media(min-width:1400px){.overview-flow{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:1100px){.overview-body{grid-template-columns:1fr}.overview-stats{gap:10px}.overview-stats article{padding:16px}.summary-groups{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:740px){.overview-stats,.summary-groups{grid-template-columns:repeat(2,minmax(0,1fr))}.workspace-intro{padding:22px}.workspace-intro svg{display:none}.overview-flow{grid-template-columns:1fr}}
</style>
